def _query_id(query):
    if not isinstance(query, dict):
        return None
    qid = query.get("id")
    if qid in ("nda-5", "nda-7", "nda-16", "nda-20"):
        return qid
    text = query.get("text")
    if not isinstance(text, str):
        return None
    text = text.lower()
    if re.search(r"\bretain\w*\b", text) and re.search(r"\b(?:after|return\w*|destr\w*)\b", text):
        return "nda-20"
    if re.search(r"\b(?:return\w*|destr\w*)\b", text) and re.search(r"\b(?:termination|terminate\w*|expiration|expiry)\b", text):
        return "nda-16"
    if re.search(r"\b(?:share\w*|disclos\w*|access)\b", text) and re.search(r"\b(?:third[- ]part\w*|consultant\w*|agent\w*|advis(?:er|or)\w*)\b", text):
        return "nda-7"
    if re.search(r"\b(?:share\w*|disclos\w*|access)\b", text) and re.search(r"\bemploye\w*\b", text):
        return "nda-5"
    return None


def _paragraphs(document):
    result = []
    for match in re.finditer(r"[^\r\n]+", document):
        quote = match.group(0)
        if re.search(r"\S", quote):
            result.append(quote)
    return result


def _ci_context(paragraphs, index):
    current = paragraphs[index]
    if re.search(r"\bconfidential\s+(?:and\s+proprietary\s+)?information\b", current, re.I):
        return True
    if not re.search(r"\b(?:the same|thereof|such information|it|access|disclos\w*|share\w*)\b", current, re.I):
        return False
    start = max(0, index - 8)
    for prior_index in range(index - 1, start - 1, -1):
        if re.search(r"\bconfidential\s+(?:and\s+proprietary\s+)?information\b", paragraphs[prior_index], re.I):
            return True
    return False


def _evidence(paragraphs, index):
    current = paragraphs[index]
    if re.search(r"\bconfidential\s+(?:and\s+proprietary\s+)?information\b", current, re.I):
        return [current]
    start = max(0, index - 8)
    for prior_index in range(index - 1, start - 1, -1):
        prior = paragraphs[prior_index]
        if re.search(r"\bconfidential\s+(?:and\s+proprietary\s+)?information\b", prior, re.I):
            return [prior, current]
    return [current]


def _target(paragraph, terms):
    action = r"(?:disclos\w*|share\w*|reveal\w*|communicat\w*|divulg\w*|transfer\w*|make\w*\s+(?:accessible|available)|restrict\w*\s+access|limit\w*\s+access|access)"
    pattern = action + r".{0,700}(?:\bto\b|\bwith\b|\bby\b|\bamong\b).{0,140}(?:" + terms + r")"
    if re.search(pattern, paragraph, re.I):
        return True
    pattern = r"(?:permit\w*|allow\w*|give\w*).{0,120}(?:" + terms + r").{0,100}\baccess\b"
    return re.search(pattern, paragraph, re.I) is not None


def _employee_target(paragraph, representative_has_employees):
    direct_terms = r"employees?|personnel"
    if _target(paragraph, direct_terms):
        for match in re.finditer(r"\b(?:employees?|personnel)\b", paragraph, re.I):
            left = paragraph[max(0, match.start() - 90):match.start()]
            foreign = re.search(r"(?:disclosing|originating|other)\s+party(?:['’]s)?[^.;:]{0,45}$", left, re.I)
            affiliate = re.search(r"affiliat(?:e|es)(?:['’]s?)?[^.;:]{0,55}$", left, re.I)
            if foreign is None and affiliate is None:
                return True
    if representative_has_employees and _target(paragraph, r"representatives?"):
        return True
    return False


def _third_party_target(paragraph):
    terms = r"third[- ]part(?:y|ies)|other\s+(?:persons?|organizations?|entities)|contractors?|agents?|advis(?:ers?|ors?)|consultants?|accountants?|attorneys?|lawyers?|lenders?|affiliates?|representatives?"
    return _target(paragraph, terms)


def _authorized(paragraph, terms):
    action = r"(?:disclos\w*|share\w*|reveal\w*|communicat\w*|make\w*\s+(?:accessible|available)|give\w*\s+access)"
    patterns = [
        r"\bmay\b.{0,180}" + action + r".{0,700}(?:" + terms + r")",
        r"\b(?:permitted|authorized|entitled)\b.{0,100}\bto\b.{0,160}" + action + r".{0,700}(?:" + terms + r")",
        r"\b(?:restrict|limit)\w*\b.{0,100}\b(?:access|disclosure)\b.{0,700}(?:" + terms + r")",
        r"\b(?:access|disclosure)\b.{0,100}\b(?:restricted|limited)\b.{0,700}(?:" + terms + r")",
        r"\bexcept\b.{0,220}\bto\b.{0,140}(?:" + terms + r")",
        r"\b(?:only|solely)\b.{0,160}\bto\b.{0,140}(?:" + terms + r")",
        r"\b(?:allow|permit)\w*\b.{0,120}(?:" + terms + r").{0,100}\baccess\b"
    ]
    for pattern in patterns:
        if re.search(pattern, paragraph, re.I):
            return True
    return False


def _negative_share(paragraph):
    action = r"(?:disclos\w*|share\w*|reveal\w*|communicat\w*|divulg\w*|transfer\w*|make\w*\s+(?:accessible|available))"
    patterns = [
        r"\b(?:shall|must|will|may)\b.{0,30}\bnot\b.{0,220}" + action,
        r"\bnot\s+to\b.{0,100}" + action,
        r"\bneither\b.{0,300}" + action,
        r"\bprohibit\w*\b.{0,180}" + action
    ]
    for pattern in patterns:
        if re.search(pattern, paragraph, re.I):
            return True
    return False


def _compile_graph(document):
    paragraphs = _paragraphs(document)
    complete = re.search(r"\bconfidential\s+(?:and\s+proprietary\s+)?information\b", document, re.I) is not None
    complete = complete and re.search(r"\b(?:recipient|receiving\s+party|disclosing\s+party|discloser|originating\s+party|non[- ]disclosure|nondisclosure)\b", document, re.I) is not None
    graph = {"policy_id": "induced-confidentiality-policy", "scopes": [], "rules": [], "complete_query_ids": [], "unresolved": []}
    if not complete:
        graph["unresolved"].append("The document was not recognized as a confidentiality agreement with role-bearing Confidential Information provisions.")
        return graph

    representative_has_employees = False
    for paragraph in paragraphs:
        if re.search(r"[\"“]?representatives?[\"”]?\s+(?:means|shall\s+mean|includes?)\b", paragraph, re.I):
            if re.search(r"\b(?:employees?|personnel)\b", paragraph, re.I):
                representative_has_employees = True

    def add_rule(effect, action, domains, triggers, conditions, quotes):
        scope_id = "scope-" + str(len(graph["scopes"]) + 1)
        rule_id = "rule-" + str(len(graph["rules"]) + 1)
        graph["scopes"].append({"id": scope_id, "domains": domains, "source_quotes": quotes})
        graph["rules"].append({"id": rule_id, "effect": effect, "action": action, "scope_id": scope_id, "triggers": triggers, "conditions": conditions, "source_quotes": quotes, "overrides": []})

    for index in range(len(paragraphs)):
        paragraph = paragraphs[index]
        if not _ci_context(paragraphs, index):
            continue
        quotes = _evidence(paragraphs, index)

        employee_target = _employee_target(paragraph, representative_has_employees)
        employee_terms = r"employees?|personnel|representatives?"
        if employee_target:
            if _authorized(paragraph, employee_terms):
                add_rule("permission", "share", ["employees"], ["unconditional"], ["limited to the expressly authorized recipient subset"], quotes)
            elif _negative_share(paragraph):
                add_rule("prohibition", "share", ["employees"], ["unconditional"], [], quotes)

        third_target = _third_party_target(paragraph)
        third_terms = r"third[- ]part(?:y|ies)|other\s+(?:persons?|organizations?|entities)|contractors?|agents?|advis(?:ers?|ors?)|consultants?|accountants?|attorneys?|lawyers?|lenders?|affiliates?|representatives?"
        if third_target:
            if _authorized(paragraph, third_terms):
                add_rule("permission", "share", ["third_parties"], ["unconditional"], ["limited to the expressly authorized recipient subset"], quotes)
            elif _negative_share(paragraph):
                add_rule("prohibition", "share", ["third_parties"], ["unconditional"], [], quotes)

        return_action = re.search(r"\b(?:return\w*|destr(?:oy|uction|oyed|oying))\b", paragraph, re.I) is not None
        termination = re.search(r"\b(?:upon|on|after|at)\s+(?:the\s+)?(?:termination|expiration|expiry)\b|\bwhen\s+(?:this\s+)?agreement\s+terminates\b", paragraph, re.I) is not None
        if return_action and termination:
            positive_return = re.search(r"\b(?:shall|must|required\s+to|agrees?\s+to|will)\b.{0,450}\b(?:return\w*|destr(?:oy|uction))\b", paragraph, re.I) is not None
            negative_return = re.search(r"\b(?:shall|must|will)\s+not\b.{0,240}\b(?:return\w*|destr(?:oy|uction))\b|\b(?:need\s+not|not\s+required\s+to|no\s+obligation\s+to)\b.{0,180}\b(?:return\w*|destr(?:oy|uction))\b", paragraph, re.I) is not None
            if positive_return and not re.search(r"\b(?:shall|must|will)\s+not\b.{0,450}\b(?:return\w*|destr(?:oy|uction))\b", paragraph, re.I):
                add_rule("obligation", "return_or_destroy", ["recipient"], ["termination"], [], quotes)
            elif negative_return:
                add_rule("prohibition", "return_or_destroy", ["recipient"], ["termination"], [], quotes)

        relation = return_action and re.search(r"\b(?:retain\w*|retention|archiv\w*|keep|kept|keeping)\b", paragraph, re.I) is not None
        if relation:
            retain_permission = re.search(r"\bmay\b.{0,100}\b(?:retain|keep|maintain)\w*\b|\b(?:permitted|entitled|authorized)\b.{0,100}\b(?:retain|keep|maintain)\w*\b|\bexcept\b.{0,220}\b(?:retain|keep|archiv)\w*\b|\b(?:need\s+not|not\s+required\s+to)\b.{0,120}\b(?:return|destroy)\w*\b.{0,180}\b(?:copy|copies)\b", paragraph, re.I) is not None
            retain_prohibition = re.search(r"\b(?:shall|must|may|will)\s+not\b.{0,160}\bretain\w*\b|\bno\b.{0,100}\b(?:copy|copies)\b.{0,100}\b(?:retain|kept)\w*\b|\bwithout\b.{0,80}\bretain\w*\b", paragraph, re.I) is not None
            if retain_permission:
                add_rule("permission", "retain", ["recipient"], ["after_return_or_destruction"], ["express post-return retention exception"], quotes)
            elif retain_prohibition:
                add_rule("prohibition", "retain", ["recipient"], ["after_return_or_destruction"], [], quotes)

    for permission in graph["rules"]:
        if permission["effect"] != "permission":
            continue
        permission_scope = None
        for scope in graph["scopes"]:
            if scope["id"] == permission["scope_id"]:
                permission_scope = scope
        if permission_scope is None:
            continue
        for prohibition in graph["rules"]:
            if prohibition["effect"] != "prohibition" or prohibition["action"] != permission["action"]:
                continue
            prohibition_scope = None
            for scope in graph["scopes"]:
                if scope["id"] == prohibition["scope_id"]:
                    prohibition_scope = scope
            if prohibition_scope is not None and any(domain in prohibition_scope["domains"] for domain in permission_scope["domains"]):
                permission["overrides"].append(prohibition["id"])

    graph["complete_query_ids"] = ["nda-5", "nda-7", "nda-16", "nda-20"]
    return graph


def infer(document, query):
    if not isinstance(document, str) or not document.strip():
        return {"answer": None, "evidence": []}
    query_id = _query_id(query)
    if query_id is None:
        return {"answer": None, "evidence": []}
    graph = _compile_graph(document)
    if query_id not in graph["complete_query_ids"]:
        return {"answer": None, "evidence": []}
    return scope_answer(graph, document, query_id)

def _uniq(items):
    out = []
    for item in items:
        if item and item not in out:
            out.append(item)
    return out


def _segments(document):
    out = []
    pattern = r'[^.!?\n]+(?:[.!?]+(?=\s|$)|(?=\n|$))'
    for match in re.finditer(pattern, document):
        text = match.group(0).strip(' \t\r\n')
        if text:
            out.append(text)
    return out


def _has_any(text, words):
    for word in words:
        if word in text:
            return True
    return False


def _definition_label(segment):
    pattern = r'[“"\']([^”"\']{1,60})[”"\']\s+(?:as used herein\s+)?(?:shall\s+)?(?:mean|means|include|includes)\b'
    match = re.search(pattern, segment, re.I)
    if match:
        return match.group(1).strip().lower()
    pattern = r'\b(representatives?|personnel|affiliates?|authorized persons?|permitted recipients?)\b\s+(?:as used herein\s+)?(?:shall\s+)?(?:mean|means|include|includes)\b'
    match = re.search(pattern, segment, re.I)
    if match:
        return match.group(1).strip().lower()
    return ''


def _linked_definitions(segments, authorization):
    low = authorization.lower()
    out = []
    for segment in segments:
        label = _definition_label(segment)
        if not label:
            continue
        variants = [label]
        if label.endswith('s'):
            variants.append(label[:-1])
        else:
            variants.append(label + 's')
        linked = False
        for variant in variants:
            if variant and variant in low:
                linked = True
        if linked:
            out.append(segment)
    return _uniq(out)


def _share_authorization(segment):
    low = segment.lower()
    if not _has_any(low, ['confidential', 'proprietary information', 'information', 'data']):
        return False
    positive_patterns = [
        r'\bmay\s+(?:also\s+)?(?:disclose|share|provide|give|furnish|make\s+available)',
        r'\b(?:permitted|entitled|authorized|allowed)\s+to\s+(?:disclose|share|provide|give|furnish|make\s+available)',
        r'\brestrict(?:ed|s|ing)?\s+access\b[^.;]{0,240}\bto\b',
        r'\baccess\b[^.;]{0,120}\b(?:limited|restricted)\b[^.;]{0,120}\bto\b',
        r'\bdisclos(?:e|ure)\b[^.;]{0,160}\b(?:permitted|allowed|necessary)\b[^.;]{0,120}\bto\b',
        r'\bmay\s+(?:be\s+given|have|receive)\s+access\b'
    ]
    for pattern in positive_patterns:
        if re.search(pattern, low, re.I):
            return True
    if 'except' in low and re.search(r'\bnot\b[^.;]{0,180}\bdisclos', low, re.I):
        tail = low[low.find('except'):]
        if _has_any(tail, ['employee', 'personnel', 'staff', 'contractor', 'consultant', 'agent', 'adviser', 'advisor', 'attorney', 'accountant', 'affiliate', 'representative', 'third party', 'third-party', 'authorized person', 'permitted recipient']):
            if ' to ' in tail or ' with ' in tail or 'access' in tail:
                return True
    return False


def _share_domains(text):
    low = text.lower()
    domains = []
    employee_present = _has_any(low, ['employee', 'personnel'])
    staff_present = 'staff' in low
    other_employee = _has_any(low, [
        "disclosing party's employees", "discloser's employees",
        "originating party's employees", "other party's employees",
        'employees of the disclosing party', 'employees of discloser',
        'employees of the originating party', 'staff of the practice',
        "originating party's staff", "disclosing party's staff"
    ])
    recipient_employee = _has_any(low, [
        "receiving party's employees", "recipient's employees",
        "receiving party’s employees", "recipient’s employees",
        'its employees', 'such employees', 'all employees',
        'employees, agents', 'employees and agents'
    ])
    recipient_staff = _has_any(low, [
        "receiving party's staff", "recipient's staff",
        "receiving party’s staff", "recipient’s staff",
        'its staff', 'such staff'
    ])
    if employee_present and (not other_employee or recipient_employee):
        domains.append('employees')
    if staff_present and recipient_staff:
        domains.append('employees')
    third_roles = [
        'contractor', 'consultant', 'agent', 'adviser', 'advisor',
        'attorney', 'lawyer', 'accountant', 'auditor', 'lender',
        'affiliate', 'professional adviser', 'professional advisor'
    ]
    if _has_any(low, third_roles):
        domains.append('third_parties')
    third_positive = False
    if re.search(r'\bmay\b[^.;]{0,100}\b(?:disclose|share|provide|give)\b[^.;]{0,120}\bthird[- ]part', low, re.I):
        third_positive = True
    if 'except' in low:
        tail = low[low.find('except'):]
        if _has_any(tail, ['third party', 'third-party']):
            third_positive = True
    if third_positive:
        domains.append('third_parties')
    return _uniq(domains)


def _share_conditions(text):
    low = text.lower()
    out = []
    if 'need-to-know' in low or 'need to know' in low:
        out.append('authorized recipients must have a need to know')
    if 'necessary' in low and _has_any(low, ['purpose', 'evaluation', 'relationship', 'transaction']):
        out.append('disclosure must be necessary for the stated purpose')
    elif _has_any(low, ['for the purpose', 'carry out the purpose', 'pursuit of the approved purpose', 'analyze the business relationship']):
        out.append('disclosure is limited to the stated purpose')
    if _has_any(low, ['in confidence', 'confidentiality obligation', 'obligated to protect', 'obliged to protect', 'bound by confidentiality']):
        out.append('authorized recipients must preserve confidentiality')
    if _has_any(low, ['no less protective', 'at least as protective']):
        out.append('recipient protections must meet the stated protective standard')
    if _has_any(low, ['responsible for ensuring compliance', 'liable for any failure', 'responsible for the performance']):
        out.append('the receiving party remains responsible for recipient compliance')
    if _has_any(low, ['prior written consent', 'prior written approval', 'expressly authorized in writing']):
        out.append('the stated prior written authorization is required')
    return _uniq(out)


def _information_context(text):
    low = text.lower()
    return _has_any(low, ['confidential information', 'proprietary information', 'copies', 'documents and materials', 'confidential data', 'materials containing', 'records containing'])


def _return_action(text):
    return bool(re.search(r'\b(?:return|returned|returning|destroy|destroyed|destroying|destruction)\b', text, re.I))


def _return_obligation(text):
    low = text.lower()
    if not _return_action(text) or not _information_context(text):
        return False
    if _has_any(low, ['shall not be required to return', 'shall not return', 'no obligation to return', 'need not return', 'not required to destroy']):
        return False
    if re.search(r'\b(?:shall|must)\b', low, re.I):
        return True
    if re.search(r'\b(?:agrees|undertakes|required)\s+to\b[^.;]{0,100}\b(?:return|destroy)', low, re.I):
        return True
    if re.search(r'\bwill\s+(?:promptly\s+|immediately\s+)?(?:return|destroy)', low, re.I):
        return True
    return False


def _return_triggers(text):
    low = text.lower()
    out = []
    if _has_any(low, ['termination', 'terminate this agreement', 'expiration', 'expiry', 'agreement expires', 'end of this agreement', 'agreement ends']):
        out.append('termination')
    if _has_any(low, ['written request', 'upon request', 'on request', 'at the request', 'written demand', 'upon demand']):
        out.append('request')
    if _has_any(low, ['completion of the purpose', 'completion of discussions', 'end of discussions', 'conclusion of discussions', 'cessation of the relationship']):
        out.append('other')
    if not out:
        out.append('other')
    return _uniq(out)


def _return_conditions(text):
    low = text.lower()
    out = []
    if 'all copies' in low:
        out.append('all copies covered by the quoted clause')
    if _has_any(low, ['at discloser’s option', "at discloser's option", 'at the option of the disclosing party', 'at disclosing party’s option']):
        out.append('the disclosing party selects return or destruction')
    if _has_any(low, ['certify in writing', 'written certification', 'certification in writing']):
        out.append('written certification of compliance is required')
    if _has_any(low, ['immediately', 'within ', 'not later than', 'promptly']):
        out.append('the timing requirement stated in the quoted clause applies')
    return _uniq(out)


def _retain_permission(text):
    low = text.lower()
    if _has_any(low, ['may not retain', 'shall not retain', 'must not retain', 'will not retain', 'not permitted to retain']):
        return False
    patterns = [
        r'\bmay\s+retain\b', r'\bmay\s+be\s+retained\b',
        r'\b(?:permitted|entitled|allowed|authorized)\s+to\s+retain\b',
        r'\bexcept\b[^.;]{0,180}\bretain\b',
        r'\bretain(?:ed)?\b[^.;]{0,100}\b(?:archival|backup|legal|compliance)\s+(?:copy|copies|purpose)'
    ]
    for pattern in patterns:
        if re.search(pattern, low, re.I):
            return True
    return False


def _explicit_retention_relation(text):
    low = text.lower()
    state_words = _has_any(low, ['return', 'returned', 'destroy', 'destroyed', 'destruction'])
    relation_words = _has_any(low, ['except', 'provided', 'however', 'notwithstanding', 'after ', 'following ', 'despite', 'subject to', 'archival', 'backup'])
    return state_words and relation_words


def _retention_conditions(text):
    low = text.lower()
    out = []
    if 'archival' in low:
        out.append('retention is solely for the stated archival purpose')
    if 'backup' in low:
        out.append('retention is limited to the stated backup-copy context')
    if _has_any(low, ['legal requirement', 'required by law', 'legal or regulatory', 'compliance purpose']):
        out.append('retention is limited to the stated legal or compliance purpose')
    if re.search(r'\b(?:one|a single)\s+copy\b', low, re.I):
        out.append('only the stated single copy may be retained')
    if _has_any(low, ['remain subject to', 'continue to be subject to', 'kept confidential']):
        out.append('retained information remains subject to confidentiality duties')
    return _uniq(out)


def infer(document, query):
    graph = {
        'policy_id': 'neutral-nda-policy',
        'scopes': [],
        'rules': [],
        'complete_query_ids': [],
        'unresolved': []
    }
    query_ids = ['nda-5', 'nda-7', 'nda-16', 'nda-20']
    if not isinstance(document, str) or not document.strip():
        graph['unresolved'] = list(query_ids)
        if query is None:
            return graph
        return scope_answer(graph, document, query)

    segments = _segments(document)
    scope_number = 0
    rule_number = 0
    unresolved_share = False

    for index, segment in enumerate(segments):
        if not _share_authorization(segment):
            continue
        authorization_quotes = [segment]
        semantic_text = segment
        if index + 1 < len(segments):
            following = segments[index + 1]
            following_low = following.lower()
            if _has_any(following_low, ['all such employees', 'such employees, agents', 'such personnel', 'such representatives']):
                authorization_quotes.append(following)
                semantic_text = semantic_text + ' ' + following
        definitions = _linked_definitions(segments, semantic_text)
        scope_text = semantic_text
        for definition in definitions:
            scope_text = scope_text + ' ' + definition
        domains = _share_domains(scope_text)
        if not domains:
            low = semantic_text.lower()
            if _has_any(low, ['authorized person', 'permitted recipient', 'representative', 'designated recipient']):
                unresolved_share = True
            continue
        scope_number += 1
        scope_id = 'scope-' + str(scope_number)
        graph['scopes'].append({
            'id': scope_id,
            'domains': domains,
            'source_quotes': _uniq(authorization_quotes + definitions)
        })
        rule_number += 1
        overrides = []
        if 'except' in semantic_text.lower() or 'restrict access' in semantic_text.lower():
            overrides.append('general nondisclosure restriction')
        graph['rules'].append({
            'id': 'rule-' + str(rule_number),
            'effect': 'permission',
            'action': 'share',
            'scope_id': scope_id,
            'triggers': ['unconditional'],
            'conditions': _share_conditions(scope_text),
            'source_quotes': _uniq(authorization_quotes),
            'overrides': overrides
        })

    return_segments = []
    for index, segment in enumerate(segments):
        context = segment
        context_quotes = [segment]
        if _return_action(segment) and index > 0:
            previous = segments[index - 1]
            previous_low = previous.lower()
            if _has_any(previous_low, ['upon termination', 'on termination', 'upon expiration', 'upon request', 'at the end of this agreement']):
                context = previous + ' ' + context
                context_quotes = [previous, segment]
        if not _return_obligation(context):
            continue
        return_segments.append((index, context, context_quotes))
        scope_number += 1
        scope_id = 'scope-' + str(scope_number)
        graph['scopes'].append({
            'id': scope_id,
            'domains': ['recipient'],
            'source_quotes': _uniq(context_quotes)
        })
        rule_number += 1
        graph['rules'].append({
            'id': 'rule-' + str(rule_number),
            'effect': 'obligation',
            'action': 'return_or_destroy',
            'scope_id': scope_id,
            'triggers': _return_triggers(context),
            'conditions': _return_conditions(context),
            'source_quotes': _uniq(context_quotes),
            'overrides': []
        })

    unresolved_retention = False
    for index, segment in enumerate(segments):
        if not _retain_permission(segment) or not _information_context(segment):
            continue
        relation = _explicit_retention_relation(segment)
        quotes = [segment]
        combined = segment
        if not relation and index > 0:
            previous = segments[index - 1]
            if _return_obligation(previous):
                relation = True
                quotes = [previous, segment]
                combined = previous + ' ' + segment
        if not relation and index > 1:
            previous = segments[index - 1]
            earlier = segments[index - 2]
            if _has_any(segment.lower(), ['foregoing', 'above', 'such return', 'such destruction']) and _return_obligation(earlier + ' ' + previous):
                relation = True
                quotes = [earlier, previous, segment]
                combined = earlier + ' ' + previous + ' ' + segment
        if not relation:
            if _has_any(segment.lower(), ['foregoing', 'above return', 'such return', 'such destruction']):
                unresolved_retention = True
            continue
        scope_number += 1
        scope_id = 'scope-' + str(scope_number)
        graph['scopes'].append({
            'id': scope_id,
            'domains': ['recipient'],
            'source_quotes': _uniq(quotes)
        })
        rule_number += 1
        graph['rules'].append({
            'id': 'rule-' + str(rule_number),
            'effect': 'permission',
            'action': 'retain',
            'scope_id': scope_id,
            'triggers': ['after_return_or_destruction'],
            'conditions': _retention_conditions(combined),
            'source_quotes': _uniq(quotes),
            'overrides': ['return or destruction obligation']
        })

    unresolved_ids = []
    if unresolved_share:
        unresolved_ids.extend(['nda-5', 'nda-7'])
    if unresolved_retention:
        unresolved_ids.append('nda-20')
    graph['unresolved'] = _uniq(unresolved_ids)
    for query_id in query_ids:
        if query_id not in graph['unresolved']:
            graph['complete_query_ids'].append(query_id)

    if query is None:
        return graph
    return scope_answer(graph, document, query)
